_OCC_REPO_NAME = "onex_change_control"
_OCC_OWNER = "OmniNode-ai"


def _is_occ_repo(repo: str) -> bool:
    cleaned = repo.strip().rstrip("/")
    parts = cleaned.split("/", maxsplit=1)
    if len(parts) == 1:
        return parts[0] == _OCC_REPO_NAME
    if len(parts) == 2:
        return parts[0] == _OCC_OWNER and parts[1] == _OCC_REPO_NAME
    return False
